 MACDX:{name:'کراس MACD',nameEn:'MACD signal cross',params:{zero:P('فقط سمت درست صفر (۰/۱)',1,0,1,1,'Zero-line filter (0/1)'),trend:P('فیلتر EMA (۰=خاموش)',200,0,400,10,'Trend EMA (0=off)')},
  overlays:p=>p.trend?[['ema',[p.trend]]]:[],
  sig:(p,i)=>{const M=I('macd');if(M.sig[i-1]==null)return null;const T=p.trend?I('ema',p.trend):null;if(T&&T[i]==null)return null;const c=K[i].c;const up=M.m[i]>M.sig[i]&&M.m[i-1]<=M.sig[i-1],dn=M.m[i]<M.sig[i]&&M.m[i-1]>=M.sig[i-1];if(up&&(!p.zero||M.m[i]<0)&&(!T||c>T[i]))return 'LONG';if(dn&&(!p.zero||M.m[i]>0)&&(!T||c<T[i]))return 'SHORT';return null;}},
 ADXDI:{name:'کراس DI با ADX',nameEn:'DI cross with ADX',params:{n:P('طول',14,7,30,1,'Length'),thr:P('حداقل ADX',20,10,40,1,'Min ADX')},overlays:()=>[],
  sig:(p,i)=>{const A=I('adx',p.n);if(A.adx[i]==null||A.pdi[i-1]==null)return null;if(A.adx[i]<p.thr)return null;if(A.pdi[i]>A.ndi[i]&&A.pdi[i-1]<=A.ndi[i-1])return 'LONG';if(A.pdi[i]<A.ndi[i]&&A.pdi[i-1]>=A.ndi[i-1])return 'SHORT';return null;}},
