let RES=null,view='ovw',NVIS=140,off=0,sel=-1;
const inp=(id,val,extra='')=>`<input id="${id}" value="${val}" ${extra} style="width:100%;background:var(--card2);color:var(--txt);border:1px solid var(--border);border-radius:8px;padding:6px;font-size:12px;direction:ltr">`;
const selEl=(id,opts,val)=>`<select id="${id}" style="width:100%;background:var(--card2);color:var(--txt);border:1px solid var(--border);border-radius:8px;padding:6px;font-size:12px">${opts.map(([v,l])=>`<option value="${v}" ${String(v)===String(val)?'selected':''}>${l}</option>`).join('')}</select>`;
const fld=(label,html)=>`<div class="field" style="margin:0"><label style="font-size:11px">${label}</label>${html}</div>`;
