   <div class="row3" style="margin-top:6px">${fld(T.tp,inp('btTp',cfg.x.tp,'type="number" step="0.25" min="0.5"'))}${fld(T.trail,inp('btTrail',cfg.x.trail,'type="number" step="0.5" min="0"'))}${fld(T.maxBars,inp('btMax',cfg.x.maxBars,'type="number" step="1" min="2"'))}</div>
