function stratSeries(){const ov=[];const S=STR[RES.strat];try{ov.push(...S.overlays(RES.p));}catch(e){}const out=[];
 for(const [name,args] of ov){const v=I(name,...args);if(!v)continue;if(name==='ema')out.push({id:'ema'+args[0],series:{v},colors:{v:args[0]<=20?'#38bdf8':args[0]<=50?'#f59e0b':'#a78bfa'},opts:{label:'EMA'+args[0],titles:{v:''}}});
  else if(name==='ichi')out.push({id:'ichi',series:{ten:v.ten,kij:v.kij,sa:v.sa,sb:v.sb},colors:{ten:'#0496ff',kij:'#991515',sa:'rgba(38,166,154,.9)',sb:'rgba(239,83,80,.9)'},opts:{label:'Ichimoku('+args.join(',')+')',cloud:['sa','sb']}});
  else if(name==='st')out.push({id:'st',series:{st:v.line},colors:{st:'#10b981'},opts:{label:'Supertrend('+args.join(',')+')',titles:{st:''}}});
  else if(name==='bb')out.push({id:'bb',series:{up:v.up,mid:v.mid,lo:v.lo},colors:{up:'#94a3b8',mid:'#94a3b8',lo:'#94a3b8'},opts:{label:'BB('+args.join(',')+')',dash:{up:1,lo:1}}});
  else if(name==='don')out.push({id:'don',series:{hh:v.hh,ll:v.ll},colors:{hh:'#f472b6',ll:'#f472b6'},opts:{label:'Donchian('+args[0]+')',dash:{hh:1,ll:1}}});}
 return out;}
function tradeMarks(){const tr=RES.tr;const m=[];tr.forEach((x,k)=>{const LG=x.side==='LONG';const c=x.rr>0?'#26a69a':'#ef5350';const isSel=k===sel;const tj=K[x.j]?K[x.j].t:x.t;
 if(isSel){m.push({kind:'zone',t:x.t,price:x.entry,t2:tj,price2:x.sl0,color:'rgba(239,83,80,.14)'});m.push({kind:'zone',t:x.t,price:x.entry,t2:tj,price2:x.tp,color:'rgba(38,166,154,.14)'});}
 m.push({kind:'line',t:x.t,price:x.entry,t2:tj,price2:x.exit,color:c,big:isSel});m.push({kind:'mark',t:x.t,price:LG?x.entry:x.entry,side:x.side,big:isSel,text:isSel?('#'+(k+1)+' '+x.side):''});m.push({kind:'dot',t:tj,price:x.exit,color:c,big:isSel,above:x.rr>0,text:(isSel||tr.length<=60)?`${sgn(x.rr)}${x.rr.toFixed(1)}R`:''});});return m;}
